mapper.select:
SELECT id, name, era, category, description, image_url, images, status, create_time, update_time
FROM artifact
WHERE deleted = 0

    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND era = #{era}


    AND category = #{category}


    AND status = #{status}

ORDER BY create_time DESC
